import{_ as l,o,c as t,a2 as e}from"./chunks/framework.BXA5Pi9t.js";const h=JSON.parse('{"title":"2019-04-01:: Ceph Orchestration Meeting","description":"","frontmatter":{"title":"2019-04-01:: Ceph Orchestration Meeting","date":"2019-04-01T00:00:00.000Z","updated":"2019-04-10T00:00:00.000Z","tags":["Ceph","Rook","CI","CSI","Orchestration"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2019/2019-04-01_-_-_Ceph_Orchestration_Meeting.md","filePath":"posts/2019/2019-04-01_-_-_Ceph_Orchestration_Meeting.md","lastUpdated":1780460162000}'),r={name:"posts/2019/2019-04-01_-_-_Ceph_Orchestration_Meeting.md"};function s(n,i,a,p,_,C){return o(),t("div",null,[...i[0]||(i[0]=[e('<h3 id="会议纪要" tabindex="-1">会议纪要 <a class="header-anchor" href="#会议纪要" aria-label="Permalink to &quot;会议纪要&quot;">​</a></h3><p><strong>会议时间</strong>： 8月某日（具体日期未知）</p><p><strong>参会人员</strong>： 多位Ceph研发人员及字幕翻译人员</p><p><strong>会议主题</strong>： 讨论Ceph项目进展、问题及解决方案</p><p><strong>关键细节</strong>：</p><ul><li><strong>会议安排</strong>： 由于其他会议的重要性，原定于周六的Ceph on 2009会议可能无法进行。会议参与者关注SAGE会议，并考虑在晚些时候安排面对面会议。</li><li><strong>系统命名服务变更</strong>： 讨论了Hamill重构的进展，需要根据新评论进行更新，这将影响LM工作，因此需要优先处理。</li><li><strong>Rook项目进展</strong>： 讨论了Rook的CI和CSI支持，外部集群支持，版本管理以及与Toothpick的集成。</li><li><strong>CI问题</strong>： 讨论了CI效率低下和维护人员不足的问题，并计划增加CI覆盖范围。</li><li><strong>Rook与Person 3和Terraform的兼容性</strong>。</li></ul><p><strong>主要议题</strong>：</p><ul><li>系统命名服务变更</li><li>Rook项目进展</li><li>CI问题</li><li>Rook与Person 3的兼容性</li><li>Rook与Terraform的集成</li></ul><p><strong>决定的事项</strong>：</p><ul><li>优先处理Hamill重构。</li><li>更新Rook的CI和CSI支持。</li><li>优化Rook的版本管理。</li><li>改进CI效率。</li><li>解决CI维护人员不足的问题。</li><li>增加CI覆盖范围。</li><li>在下周社区会议上提出CI问题。</li></ul><p><strong>后续行动计划</strong>：</p><ul><li>更新Hamill重构。</li><li>完成Rook的CI和CSI支持。</li><li>优化Rook的版本管理。</li><li>改进CI效率。</li><li>解决CI维护人员不足的问题。</li><li>增加CI覆盖范围。</li><li>在下周社区会议上提出CI问题。</li><li>探索Rook与Person 3和Terraform的集成。</li></ul><p><strong>其他</strong>：</p><ul><li>讨论了CI维护人员不足的问题，并计划在下周社区会议上提出。</li><li>讨论了如何增加CI覆盖范围，以及如何利用Susie的资源。</li><li>讨论了Rook与Toothpick的集成，以及如何支持Rook在Toothpick上的运行。</li></ul><p><strong>关键词</strong>：</p><ul><li>Ceph</li><li>Rook</li><li>CI</li><li>CSI</li><li>Toothpick</li><li>Person 3</li><li>Terraform</li><li>Hamill</li><li>LM</li><li>CI</li><li>Susie</li><li>CI</li><li>Rook</li><li>OSD</li><li>CRD</li><li>Kubernetes</li><li>Docker</li></ul>',16)])])}const c=l(r,[["render",s]]);export{h as __pageData,c as default};
